import React, { useCallback, useState } from 'react';
import { useDropzone } from 'react-dropzone';
import './App.css';

interface AnalysisResponse {
  insights: string;
  filename: string;
}

function App() {
  const [file, setFile] = useState<File | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [progress, setProgress] = useState<string[]>([]);
  const [analysis, setAnalysis] = useState<AnalysisResponse | null>(null);
  const [error, setError] = useState<string | null>(null);

  const onDrop = useCallback((acceptedFiles: File[]) => {
    if (acceptedFiles.length > 0) {
      setFile(acceptedFiles[0]);
      setError(null);
    }
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'image/*': ['.png', '.jpg', '.jpeg', '.gif'],
      'application/pdf': ['.pdf']
    },
    maxFiles: 1
  });

  const removeFile = () => {
    setFile(null);
  };

  const analyzeDocument = async () => {
    if (!file) {
      setError('Please upload a document');
      return;
    }

    setIsAnalyzing(true);
    setProgress([]);
    setAnalysis(null);
    setError(null);

    const formData = new FormData();
    formData.append('file', file);

    try {
      const response = await fetch('http://localhost:8000/api/analyze-document', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || `HTTP error! status: ${response.status}`);
      }

      const reader = response.body?.getReader();
      if (!reader) throw new Error('No reader available');

      const decoder = new TextDecoder();

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value);
        const lines = chunk.split('\n');

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = JSON.parse(line.slice(6));

            if (data.type === 'progress') {
              setProgress(prev => [...prev, data.message]);
            } else if (data.type === 'result') {
              setAnalysis(data.data);
            }
          }
        }
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error analyzing document');
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>Trade Document Analyzer</h1>
      </header>
      <main>
        <div className="upload-section">
          <div {...getRootProps()} className={`dropzone ${isDragActive ? 'active' : ''}`}>
            <input {...getInputProps()} />
            {isDragActive ? (
              <p>Drop the file here ...</p>
            ) : (
              <p>Drag 'n' drop a file here, or click to select a file</p>
            )}
          </div>

          {file && (
            <div className="file-list">
              <h3>Selected File:</h3>
              <ul>
                <li>
                  {file.name}
                  <button onClick={removeFile}>Remove</button>
                </li>
              </ul>
              <button 
                onClick={analyzeDocument} 
                disabled={isAnalyzing}
                className="analyze-button"
              >
                {isAnalyzing ? 'Analyzing...' : 'Analyze Document'}
              </button>
            </div>
          )}
        </div>

        {error && (
          <div className="error-message">
            {error}
          </div>
        )}

        {progress.length > 0 && (
          <div className="progress-section">
            <h3>Progress:</h3>
            <ul>
              {progress.map((message, index) => (
                <li key={index}>{message}</li>
              ))}
            </ul>
          </div>
        )}

        {analysis && (
          <div className="analysis-section">
            <h3>Analysis Results:</h3>
            <div className="analysis-content">
              <h4>Document: {analysis.filename}</h4>
              <h4>Key Insights:</h4>
              <p>{analysis.insights}</p>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
